//#region src/woff2/encode/transform-hmtx.ts
function transformHmtx(font, hmtxData, numHMetrics, glyphInfo) {
	const { numGlyphs, glyphOffsets } = glyphInfo;
	const glyfEntry = font.tables.get(TAG_GLYF);
	if (!glyfEntry) return null;
	const view = new DataView(hmtxData.buffer, hmtxData.byteOffset, hmtxData.byteLength);
	let canEliminateProportionalLsb = true;
	let canEliminateMonospaceLsb = numGlyphs > numHMetrics;
	const advances = [];
	const proportionalLsbs = [];
	const monospaceLsbs = [];
	let hmtxOffset = 0;
	for (let i = 0; i < numGlyphs; i++) {
		const glyphOffset = glyphOffsets[i];
		const glyphLength = glyphOffsets[i + 1] - glyphOffset;
		let xMin = 0;
		if (glyphLength > 0) {
			const glyphStart = glyfEntry.offset + glyphOffset;
			xMin = font.view.getInt16(glyphStart + 2);
		}
		if (i < numHMetrics) {
			const advance = view.getUint16(hmtxOffset);
			const lsb = view.getInt16(hmtxOffset + 2);
			hmtxOffset += 4;
			advances.push(advance);
			proportionalLsbs.push(lsb);
			if (glyphLength > 0 && lsb !== xMin) canEliminateProportionalLsb = false;
		} else {
			const lsb = view.getInt16(hmtxOffset);
			hmtxOffset += 2;
			monospaceLsbs.push(lsb);
			if (glyphLength > 0 && lsb !== xMin) canEliminateMonospaceLsb = false;
		}
		if (!canEliminateProportionalLsb && !canEliminateMonospaceLsb) return null;
	}
	let flags = 0;
	if (canEliminateProportionalLsb) flags |= 1;
	if (canEliminateMonospaceLsb) flags |= 2;
	let size = 1 + advances.length * 2;
	if (!canEliminateProportionalLsb) size += proportionalLsbs.length * 2;
	if (!canEliminateMonospaceLsb) size += monospaceLsbs.length * 2;
	if (size >= hmtxData.byteLength) return null;
	const output = new WriteBuffer(size);
	output.writeU8(flags);
	for (const advance of advances) output.writeU16(advance);
	if (!canEliminateProportionalLsb) for (const lsb of proportionalLsbs) output.writeS16(lsb);
	if (!canEliminateMonospaceLsb) for (const lsb of monospaceLsbs) output.writeS16(lsb);
	return { data: output.getBytes() };
}

